public interface QuerydslPredicateExecutor<T> {
  java.util.Optional<T> findOne(com.querydsl.core.types.Predicate);
  java.lang.Iterable<T> findAll(com.querydsl.core.types.Predicate);
  java.lang.Iterable<T> findAll(Predicate, Sort);
  Page<T> findAll(Predicate, Pageable);
  long count(Predicate);
  boolean exists(Predicate);
}

